-- Remove older references if any update m_loan set product_id = (select id from m_product_loan mpl where short_name = 'ROTA') , loan_status_id = 600 where product_id = (select id from m_product_loan mpl where short_name = 'ROTP');
delete from acc_product_mapping where product_id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_product_loan_configurable_attributes where loan_product_id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_product_loan_charge where product_loan_id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_loan_product_payment_allocation_rule where loan_product_id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_loan_product_channel where loan_product_id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_product_loan where id = (select id from m_product_loan mpl where short_name = 'ROTP'); delete from m_interest_rate where "name" = 'IC Credito Rotativo Productivo'; delete from m_interest_rate where "name" = 'Mora Crédito rotativo productivo'; delete from m_charge where "name" = 'Mora diaria crédito rotativo productivo';
